INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('google', 'TECH', 'How many searches does Google handle worldwide on an average day?', 'searches per day', 14000000000, NULL, 'Roughly 5 billion people use Google and each runs about 3 searches a day, which gives about 15 billion.', 'Google does not publish an exact figure. Published estimates run from about 8.5 to 16 billion a day. This one comes from a 5-trillion-a-year count.', 'Search Engine Land', 'https://searchengineland.com/google-5-trillion-searches-per-year-452928', '2025 estimate', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('email', 'TECH', 'How many emails are sent and received worldwide on an average day in 2026?', 'emails per day', 392500000000, NULL, 'About 4.5 billion people use email and each handles around 85 messages a day, spam included. That is about 380 billion.', 'This is a projection by Statista, reported by EmailToolTester, not a count.', 'EmailToolTester', 'https://www.emailtooltester.com/en/blog/how-many-emails-are-sent-per-day/', '2026 projection', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('iphone', 'TECH', 'How many iPhones were sold worldwide in 2025?', 'iPhones', 247000000, NULL, 'If about 1.5 billion iPhones are in use and each is replaced every six years or so, that is roughly 250 million new ones a year.', 'Apple stopped reporting iPhone unit sales in 2019, so this is an IDC estimate.', 'SQ Magazine, citing IDC', 'https://sqmagazine.co.uk/how-many-iphones-sold/', '2025 estimate', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('linux', 'CODE', 'How many lines are in the Linux kernel source tree, counting code, comments and blank lines?', 'lines', 40980000, NULL, 'Linux 4.12 had about 24 million lines in 2017. The tree grows roughly 2 million lines a year, so nine years later you land near 42 million.', 'Counts differ by tool, and one count puts the previous release above 43 million. About 6.5 million of these lines are a single GPU register dump.', 'Open Source For You, citing Phoronix', 'https://www.opensourceforu.com/2026/09/linux-kernel-heads-past-40-98m-lines-with-7-3-rc1/', 'Linux 7.3-rc1, September 2026', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('eqvol', 'MARKETS', 'How many shares changed hands per day, on average, across US stock markets in 2025?', 'shares per day', 17600000000, 'equity', 'US stocks turn over about $1 trillion a day. At an average price near $60 a share, that is roughly 17 billion shares.', 'Cboe counts every consolidated trade. The 2025 average was a record, up 44.6% on 2024.', 'Cboe, 2025 U.S. Equities Year in Review', 'https://www.cboe.com/insights/posts/2025-u-s-equities-year-in-review', '2025 daily average', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('eqnot', 'MARKETS', 'How many dollars of stock traded hands per day, on average, in US markets in 2025?', 'US dollars per day', 1100000000000, 'equity', 'About 17.6 billion shares a day at an average price around $60 comes to roughly $1 trillion.', 'Cboe reports about $1.1 trillion. Its record single day was April 9, 2025, at $1.86 trillion.', 'Cboe, 2025 U.S. Equities Year in Review', 'https://www.cboe.com/insights/posts/2025-u-s-equities-year-in-review', '2025 daily average', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('btc', 'CRYPTO', 'How many transactions did the Bitcoin network confirm per day, on average, in June 2026?', 'transactions per day', 651655, NULL, 'A block arrives about every 10 minutes, so there are 144 a day. A busy month puts a few thousand transactions in each block, which gives 400,000 to 700,000.', 'This counts confirmed on-chain transactions only. June was up 90% on June 2025.', 'GNCrypto, citing Blockchair', 'https://www.gncrypto.news/news/bitcoin-third-busiest-day-862979-transactions-june-23-2026/', 'June 2026 average', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('ghrepos', 'CODE', 'How many repositories exist on GitHub, public and private combined?', 'repositories', 630000000, 'github', 'GitHub has about 180 million developers. If each has 3 or 4 repositories (forks, experiments, private projects), that is around 600 million.', 'Public repositories are about 63% of the total.', 'It''s FOSS, citing GitHub Octoverse', 'https://itsfoss.com/news/github-octoverse-2025/', 'GitHub Octoverse 2025', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('ghnew', 'CODE', 'How many new repositories were created on GitHub every minute in 2025?', 'new repositories per minute', 230, 'github', 'GitHub added about 121 million repositories in 2025. A year has about 525,600 minutes, and 121 million ÷ 525,600 is roughly 230.', 'GitHub reports "230+" per minute.', 'It''s FOSS, citing GitHub Octoverse', 'https://itsfoss.com/news/github-octoverse-2025/', 'GitHub Octoverse 2025', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('listed', 'MARKETS', 'How many publicly listed companies are there in the world?', 'companies', 53795, NULL, 'Around 50 major exchanges, averaging about 1,000 listings each. India alone has more than 5,000 and the US several thousand, so the total lands near 50,000.', 'Estimates run from about 47,000 to 58,000 depending on the source and the year.', 'WealthBriefing, citing Investopedia', 'https://www.wealthbriefing.com/html/printarticle.php?id=205692', 'Recent estimate', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('dc', 'TECH', 'How many data centers operate in the United States?', 'data centers', 5427, NULL, 'The US holds about 45% of the world’s data centers. If the world has around 12,000, that is roughly 5,400.', 'The count depends heavily on what you call a data center. Other sources put the world total anywhere from 6,000 to over 50,000.', 'Cargoson data center roundup', 'https://www.cargoson.com/en/blog/number-of-data-centers-by-country', 'November 2025', 'live');
INSERT INTO questions (id, topic, text, unit, answer, grp, napkin, note, source_label, source_url, as_of, status) VALUES ('tsmc', 'CHIPS', 'How many 12-inch wafers can TSMC make in a year at full capacity?', '12-inch equivalent wafers per year', 17000000, NULL, 'TSMC runs about nine 12-inch fabs. At roughly 150,000 wafers a month each, that is about 1.4 million a month, or close to 17 million a year.', 'TSMC says capacity was above 17 million, so the true figure is a little higher.', 'TSMC company profile', 'https://investor.tsmc.com/japanese/fundamentals', '2025 capacity', 'live');
